# Purpose: tests for ui/typeinfo.py: a value's type as shown (list[DailyClose]), cut around
#          its model's name, and the model's class as code (as written by "/assign" or a
#          cell, read from a library's file, or rebuilt from its fields).
# Usage: uv run pytest tests/services/ui/test_typeinfo.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import sys
from pathlib import Path

from pydantic import BaseModel, Field

APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

from ui import assign, typeinfo  # noqa: E402
from ui.session import Session  # noqa: E402

DAILY = "\n".join(
    [
        "class DailyClose(BaseModel, frozen=True):",
        "    date: datetime.date  # trading day",
        "    close: float  # closing price in USD",
        "",
        "closes = [DailyClose(date=datetime.date(2025, 11, 17), close=267.46)]",
    ]
)


class Player(BaseModel, frozen=True):
    tag: str = Field(description="the player's tag")
    seed: int | None = None
    chars: list[str] = []


def test_a_lists_type_says_what_it_holds() -> None:
    assert typeinfo.type_text([Player(tag="a"), Player(tag="b")]) == "list[Player]"
    assert typeinfo.type_text([1, 2.5]) == "list[float | int]"
    assert typeinfo.type_text([]) == "list"
    assert typeinfo.type_text([1, "a", 2.0, None]) == "list"  # too mixed to say
    assert typeinfo.type_text("Steve") == "str"


def test_the_type_is_cut_around_its_model() -> None:
    parts = typeinfo.type_parts([Player(tag="a")])
    assert (parts["text"], parts["pre"], parts["model"], parts["post"]) == ("list[Player]", "list[", "Player", "]")
    assert parts["code"].startswith("class Player(BaseModel, frozen=True):")
    one = typeinfo.type_parts(Player(tag="a"))
    assert (one["pre"], one["model"], one["post"]) == ("", "Player", "")
    # no model: all of it is pre, nothing to hover
    assert typeinfo.type_parts([1, 2]) == {**typeinfo.NO_TYPE, "text": "list[int]", "pre": "list[int]"}


def test_an_assigned_class_shows_as_written_with_its_comments() -> None:
    session = Session()
    assert assign.run(session, DAILY).name == "closes"
    code = typeinfo.type_parts(session.namespace["closes"])["code"]
    assert code == "\n".join(DAILY.splitlines()[:3])


def test_a_cells_class_shows_as_written() -> None:
    session = Session()
    session.run_python(
        "from pydantic import BaseModel\nclass Point(BaseModel):\n    x: int  # across\n\np = Point(x=1)", "cell 1"
    )
    assert typeinfo.class_code(type(session.namespace["p"])) == "class Point(BaseModel):\n    x: int  # across"


def test_a_library_class_is_read_from_its_file() -> None:
    code = typeinfo.class_code(Player)
    assert 'tag: str = Field(description="the player\'s tag")' in code


def test_a_class_with_no_source_is_rebuilt_from_its_fields() -> None:
    assert typeinfo.rebuilt_code(Player) == "\n".join(
        [
            "class Player(BaseModel, frozen=True):",
            "    tag: str  # the player's tag",
            "    seed: int | None = None",
            "    chars: list[str] = []",
        ]
    )


def test_the_code_is_highlighted_and_escaped() -> None:
    html = typeinfo.code_html("class A(BaseModel):\n    x: list[int]  # <b>")
    assert '<span class="py-k">class</span>' in html
    assert '<span class="py-nc">A</span>' in html
    # the code is text, never markup
    assert "&lt;b&gt;" in html
    assert "<b>" not in html
